#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n, custos[3];
    scanf("%d%d%d%d", &n, &custos[0], &custos[1], &custos[2]);

    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (custos[i] > custos[j]) {
                int temp = custos[i];
                custos[i] = custos[j];
                custos[j] = temp;
            }
        }
    }

    int quantidade = 0;
    for (int i = 0; i < 3 && n >= custos[i]; i++) {
        n -= custos[i];
        quantidade++;
    }

    printf("%d\n", quantidade);
    return 0;
}
